"""Generate a portable, pre-rendered HTML site from one JSON configuration. No Node.js required."""
import json, html, re
from pathlib import Path
from urllib.parse import quote
R=Path(__file__).parent; D=R/'dist'; C=json.loads((D/'assets/config/site-config.json').read_text()); B=C['brand']; ORIGIN=C['seo'].get('canonicalBase') or B['domain']; CONTACT=C['contact']; P=C['programs']; E=lambda s:html.escape(str(s),quote=True)
def link(url,text,cls=''): return f'<a class="{cls}" href="{E(url)}">{text}</a>'
def icon(name):
 paths={'code':'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 16"/>','arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>','people':'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>','document':'<path d="M6 3h9l4 4v14H6zM15 3v5h4M9 12h7m-7 4h7"/>','chat':'<path d="M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4Z"/><path d="M8 10h8m-8 4h5"/>','compass':'<circle cx="12" cy="12" r="9"/><path d="m16 8-3 5-5 3 3-5z"/>','check':'<path d="m5 12 4 4L19 6"/>','clock':'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>','location':'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>','layers':'<path d="m3 7 9-5 9 5-9 5zM3 12l9 5 9-5M3 17l9 5 9-5"/>','coffee':'<path d="M4 8h13v7a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5ZM17 9h2a3 3 0 0 1 0 6h-2M8 2v3m5-3v3M3 22h16"/>'}
 return '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths.get(name,paths['code'])+'</svg>'
def money(x):return '₹'+format(x,',')
def url(p):return ('courses/' if p['type']=='course' else 'internships/')+p['id']+'.html'
def btn(to,label,secondary=False):return link(to,E(label)+' '+icon('arrow'),'btn '+('btn-outline-primary' if secondary else 'btn-primary'))
def check_list(items):return '<ul class="check-list">'+''.join('<li>'+icon('check')+E(x)+'</li>' for x in items)+'</ul>'
def heading(label,title,desc='',action=''):
 return f'<div class="section-heading"><div><span class="eyebrow">{E(label)}</span><h2>{E(title)}</h2>{f"<p>{E(desc)}</p>" if desc else ""}</div>{action}</div>'
def card(p):
 stack='java' if 'java' in p['id'] else ('frontend' if 'frontend' in p['id'] else 'fullstack'); label='JAVA + BACKEND' if stack=='java' else ('FRONTEND' if stack=='frontend' else 'FRONTEND + BACKEND')
 return f'''<article class="program-card filter-card" data-name="{E(p['name']+' '+p['description']+' '+' '.join(p['highlights']))}" data-type="{p['type']}"><div class="program-art {stack}"><span class="stack-label">{label}</span><span class="art-symbol">{icon('coffee' if stack=='java' else 'layers' if stack=='fullstack' else 'code')}</span><span class="art-code">{'public class YourFuture { }' if stack=='java' else '&lt;Build your next chapter /&gt;'}</span><span class="art-dots">•••</span></div><div class="program-body"><div class="program-meta"><span>{icon('clock')}{E(p['duration'])}</span><span>{icon('location')}{E(p['mode'])}</span></div><h3>{link(url(p),E(p['name']))}</h3><p>{E(p['description'])}</p>{check_list(p['highlights'])}<div class="program-bottom"><div><small>Program fee</small><strong>{money(p['fee'])}</strong></div>{link(url(p),'View details '+icon('arrow'),'text-link')}</div></div></article>'''
def cards(programs):return '<div class="program-grid '+('three' if len(programs)==3 else '')+'">'+''.join(card(p) for p in programs)+'</div>'
def accordion(items,id='faq'):
 return f'<div class="accordion" id="{id}">'+''.join(f'<div class="accordion-item"><h3 class="accordion-header"><button class="accordion-button collapsed" type="button" data-bs-toggle="collapse" data-bs-target="#{id}-{i}" aria-expanded="false" aria-controls="{id}-{i}"><span class="accordion-num">{i+1:02d}</span>{E(a)}</button></h3><div id="{id}-{i}" class="accordion-collapse collapse" data-bs-parent="#{id}"><div class="accordion-body">{E(b)}</div></div></div>' for i,(a,b) in enumerate(items))+'</div>'
def benefits():return '<div class="feature-grid">'+''.join(f'<article class="feature"><span class="feature-icon">{icon(i)}</span><h3>{E(t)}</h3><p>{E(d)}</p></article>' for t,d,i in C['benefits'])+'</div>'
def team():return '<div class="team-grid">'+''.join(f'<article class="team-card"><div class="avatar avatar-{i}">{E(p["initials"])}</div><h3>{E(p["name"])}</h3><span>{E(p["role"])}</span><p>{E(p["focus"])}</p></article>' for i,p in enumerate(C['team']))+'</div>'
def cta():return f'<section class="container"><div class="cta-panel"><div><span class="eyebrow">YOUR NEXT CHAPTER</span><h2>Ready to build your future<br> in technology?</h2><p>Choose your learning path and take the next step toward becoming an industry-ready developer.</p></div><div class="cta-actions">{btn("courses.html","Explore Programs")}{btn("contact.html","Contact Our Team",True)}{whatsapp()}</div></div></section>'
def whatsapp():
 n=re.sub(r'\D','',CONTACT['whatsapp'])
 return link('https://wa.me/'+n+'?text='+quote('Hi, I would like to learn about JavaWallah programs.'),'WhatsApp Enquiry '+icon('chat'),'btn btn-outline-primary') if len(n)>=10 else ''
def form(selected=''):
 options=''.join(f'<option value="{E(p["id"])}" {"selected" if selected==p["id"] else ""}>{E(p["name"])}</option>' for p in P)
 return f'''<form class="enquiry-form" novalidate><div class="form-intro"><span class="eyebrow">LET’S TALK</span><h2>Find the right program for you.</h2><p>Tell us a little about yourself. Our team can help you plan your next step.</p></div><div class="row g-3"><div class="col-sm-6"><label for="student-name" class="form-label">Student name *</label><input id="student-name" name="name" class="form-control" required minlength="2" maxlength="100" autocomplete="name"><div class="invalid-feedback">Enter your name (at least 2 characters).</div></div><div class="col-sm-6"><label for="phone" class="form-label">Phone number *</label><input id="phone" name="phone" class="form-control" required type="tel" pattern="[+0-9 ()-]{{10,20}}" autocomplete="tel"><div class="invalid-feedback">Enter a valid phone number.</div></div><div class="col-12"><label for="email" class="form-label">Email address *</label><input id="email" name="email" class="form-control" required type="email" maxlength="200" autocomplete="email"><div class="invalid-feedback">Enter a valid email address.</div></div><div class="col-12"><label for="program" class="form-label">Program of interest *</label><select id="program" name="program" required class="form-select"><option value="">Select a program</option>{options}</select><div class="invalid-feedback">Choose a program.</div></div><div class="col-sm-6"><label for="mode" class="form-label">Preferred learning mode *</label><select id="mode" name="mode" required class="form-select"><option value="">Select a mode</option><option>Offline</option><option>Online</option></select><div class="invalid-feedback">Choose an available mode.</div></div><div class="col-sm-6"><label for="education" class="form-label">Current education level *</label><select id="education" name="education" required class="form-select"><option value="">Select education level</option><option>School student</option><option>College student</option><option>Graduate</option><option>Working professional</option><option>Other</option></select><div class="invalid-feedback">Choose your education level.</div></div><div class="col-12"><label for="message" class="form-label">Anything you’d like us to know?</label><textarea id="message" name="message" class="form-control" rows="4" maxlength="3000" placeholder="Your goals, questions, or preferred schedule…"></textarea></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="consent" id="enquiry-consent" required><label for="enquiry-consent" class="form-check-label">I agree to share these details for a response to my enquiry. {link('privacy-policy.html','Privacy policy')}</label><div class="invalid-feedback">Please confirm before preparing your enquiry.</div></div></div></div><p class="form-note">No submission service is connected yet. Prepare your enquiry, then review and send it in your email app.</p><button class="btn btn-primary form-submit" type="submit">Prepare email enquiry {icon('arrow')}</button><div class="form-status" role="status" aria-live="polite"></div></form>'''
def code_visual():return '''<div class="workspace-visual" aria-label="Illustration of a Java project in a code editor"><div class="visual-orbit"></div><div class="floating-tag tag-top"><span class="mini-icon">&lt;/&gt;</span> Ideas into real projects</div><div class="code-window"><div class="window-title"><span class="traffic"><i></i><i></i><i></i></span><span>your-next-chapter.java</span><span>⌘</span></div><div class="editor-tabs"><span class="active">☕ HelloFuture.java</span><span>README.md</span></div><div class="editor-code"><div><b>01</b><span class="code-comment">// Big journeys start with small steps.</span></div><div><b>02</b><span class="code-purple">public class</span> <span class="code-yellow">YourFuture</span> {</div><div><b>03</b>  <span class="code-purple">public static void</span> main() {</div><div><b>04</b>    learn(<span class="code-green">"Java"</span>);</div><div><b>05</b>    practise(<span class="code-green">"Problem Solving"</span>);</div><div><b>06</b>    build(<span class="code-green">"Something Real"</span>);</div><div><b>07</b></div><div><b>08</b>    <span class="code-comment">// Keep learning. Keep building.</span></div><div><b>09</b>    <span class="code-purple">return</span> yourNextChapter;</div><div><b>10</b>  }</div><div><b>11</b>}</div></div><div class="terminal"><span>TERMINAL</span><p><em>➜</em> javac HelloFuture.java</p><p class="code-green">✓ Ready to build what’s next.</p></div><div class="editor-status"><span>⑂ main &nbsp; ✓ Java</span><span>UTF-8 &nbsp; Ln 9, Col 28</span></div></div><div class="build-card"><span class="build-check">✓</span><div><strong>From learning to building</strong><small>One project at a time.</small></div><span class="build-spark">↗</span></div><div class="visual-caption"><i></i> LEARN. PRACTISE. BUILD. REPEAT.</div></div>'''
def journey():return '<div class="journey">'+''.join(f'<div class="journey-step"><span>{i+1:02d}</span><h3>{E(x)}</h3></div>' for i,x in enumerate(C['journey']))+'</div>'
def workflow():return '<div class="workflow">'+''.join(f'<div><span>{i+1:02d}</span>{E(x)}</div>' for i,x in enumerate(C['workflow']))+'</div>'
def roadmap():return '<div class="career-roadmap">'+''.join(f'<article><span>{i+1:02d}</span><div><h3>{E(t)}</h3><p>{E(d)}</p></div></article>' for i,(t,d) in enumerate(C['careerRoadmap']))+'</div>'
def home():
 h=C['hero']; title=E(h['title']).replace('building a career','<em>building a career</em>')
 return f'''<section class="hero"><div class="container"><div class="hero-grid"><div class="hero-copy"><span class="hero-pill"><i></i>{E(h['eyebrow'])}</span><h1>{title}</h1><p>{E(h['description'])}</p><div class="hero-actions">{btn('courses.html','Explore Programs')}{link('contact.html','Book a Counselling Session '+icon('arrow'),'quiet-link')}</div><div class="hero-footnote">{icon('location')} {E(CONTACT['address'])}<span>•</span> A learning initiative under {link(B['parentUrl'],E(B['parentName']))}</div></div>{code_visual()}</div><div class="focus-strip">{''.join('<span>'+icon(['coffee','layers','code','compass'][i])+E(x)+'</span>' for i,x in enumerate(h['labels']))}</div></div></section>
<section class="section container">{heading('A CLEAR PATH FORWARD','Small steps. Real progress.','A structured journey from your first line of code to your next opportunity.')}{journey()}</section>
<section class="section soft" id="programs"><div class="container">{heading('OUR FLAGSHIP PROGRAMS','Build skills with a bigger purpose.','Structured courses. Consistent practice. Projects you can call your own.',link('courses.html','Explore all courses '+icon('arrow'),'text-link'))}{cards(P[:2])}<div class="path-note">{icon('layers')}<p><strong>One strong foundation. Two ways forward.</strong> Full Stack Development adds web design and frontend development to the complete Java and backend pathway.</p>{link('courses.html#compare','Compare programs '+icon('arrow'),'text-link')}</div></div></section>
<section class="section container">{heading('PRACTICE THAT COUNTS','Less watching. More building.','Focused internship programs for putting your skills to work.',link('internships.html','Explore internships '+icon('arrow'),'text-link'))}{cards(P[2:])}<p class="fineprint">{E(C['feesNote'])} {E(C['frontEndNote'])}</p></section>
<section class="section soft"><div class="container">{heading('MORE THAN A CURRICULUM','Your skills. Your confidence. Your next step.','Included in both flagship courses and the Java and Full Stack internships.')}{benefits()}</div></section>
<section class="section container"><div class="curriculum-preview"><div>{heading('BUILT FROM THE FUNDAMENTALS','Know what you’ll learn.','Explore the Java foundation shared by both flagship courses.')}{btn(url(P[1]),'See the Full Stack curriculum',True)}</div>{accordion([(m['title'],m['description']) for m in P[0]['curriculum']], 'home-curriculum')}</div></section>
<section class="section dark-section"><div class="container">{heading('THE INTERNSHIP EXPERIENCE','Go beyond theory. Build something real.','Follow a practical development workflow, from understanding the problem to demonstrating your solution.')}{workflow()}<p class="fineprint">{E(C['certificateNote'])}</p></div></section>
<section class="section container"><div class="support-layout"><div>{heading('LEARNING & CAREER SUPPORT','Grow into the developer you want to be.','Problem-solving, communication and career preparation belong alongside code.')}{btn('career-support.html','Explore career support',True)}</div>{roadmap()}</div></section>
<section class="section soft"><div class="container">{heading('THE PEOPLE IN YOUR CORNER','Meet your learning team.','Guidance for the technical challenges and the steps that come after.',link('team.html','Meet the team '+icon('arrow'),'text-link'))}{team()}</div></section>
{testimonials()}
<section class="section container faq-section"><div>{heading('A LITTLE MORE CLARITY','Good questions.<br>Clear answers.'.replace('<br>',' '),'Everything you need to take the first step.')}{link('contact.html','Still have a question? Get in touch '+icon('arrow'),'text-link')}</div>{accordion(C['faqs'])}</section>{cta()}'''
def testimonials():
 data=C['testimonials']; items=[x for x in data['items'] if x.get('approved')]
 if not data['enabled'] or not items:return ''
 return '<section class="section container">'+heading('STUDENT VOICES','In their own words.')+'<div class="feature-grid">'+''.join('<blockquote class="feature"><p>'+E(x['text'])+'</p><footer>'+E(x['name'])+' · '+E(x['program'])+'</footer></blockquote>' for x in items)+'</div></section>'
def pagehero(key,description='',title=None):
 a,b=C['pages'].get(key,[key,title or key]);return f'<section class="page-hero"><div class="container"><nav class="breadcrumbs" aria-label="Breadcrumb">{link("index.html","Home")}<span>/</span>{E(a)}</nav><span class="eyebrow">{E(a)}</span><h1>{E(title or b)}</h1>{f"<p>{E(description)}</p>" if description else ""}</div></section>'
def comparison():
 return '<div id="compare" class="comparison"><h2>Find your fit.</h2><div class="table-responsive"><table class="table"><caption>Flagship course comparison</caption><thead><tr><th scope="col">Your learning pathway</th>'+''.join('<th scope="col">'+E(p['name'])+'</th>' for p in P[:2])+'</tr></thead><tbody>'+''.join('<tr><th scope="row">'+a+'</th><td>'+b+'</td><td>'+c+'</td></tr>' for a,b,c in [('Java & backend development','Included','Included'),('DSA & interview preparation','Included','Included'),('HTML, CSS, JavaScript & React','Not included','Included'),('Integrated full-stack projects','Not included','Included'),('Career support','Included','Included'),('Duration',E(P[0]['duration']),E(P[1]['duration'])),('Program fee',money(P[0]['fee']),money(P[1]['fee']))])+'</tbody></table></div></div>'
def catalogue(type):
 ps=[p for p in P if p['type']==type];key='courses' if type=='course' else 'internships'
 search=f'<div class="catalogue-toolbar"><div class="filter-tabs" role="group" aria-label="Filter programs"><button class="filter-button active" data-filter="all" aria-pressed="true">All {key}</button><button class="filter-button" data-filter="java" aria-pressed="false">Java & Backend</button><button class="filter-button" data-filter="full stack" aria-pressed="false">Full Stack</button>'+('' if type=='course' else '<button class="filter-button" data-filter="front-end" aria-pressed="false">Front-End</button>')+'</div><label class="search-label"><span class="visually-hidden">Search programs</span><input class="form-control" id="program-search" type="search" placeholder="Search programs…"></label></div>'
 comparisonintern='<div class="comparison"><h2>Choose the experience you need.</h2><div class="table-responsive"><table class="table"><caption>Internship program comparison</caption><thead><tr><th scope="col">Program</th><th scope="col">Duration</th><th scope="col">Fee</th><th scope="col">Career support</th></tr></thead><tbody>'+''.join('<tr><th scope="row">'+E(p['name'])+'</th><td>'+E(p['duration'])+'</td><td>'+money(p['fee'])+'</td><td>'+('Included' if p['careerSupport'] else 'Practical learning only')+'</td></tr>' for p in ps)+'</tbody></table></div><p>'+E(C['frontEndNote'])+'</p></div>'
 return pagehero(key,'Build your foundation with a structured offline course in Agra.' if type=='course' else 'Practical programs, guided projects and a clear path from planning to demonstration.')+'<section class="section container">'+search+cards(ps)+'<p id="no-results" hidden role="status">No matching programs. Try a different search.</p><p class="search-result" role="status" aria-live="polite"></p>'+(comparison() if type=='course' else '<p class="fineprint">'+E(C['feesNote'])+'</p>'+comparisonintern+workflow()+'<p class="fineprint">'+E(C['certificateNote'])+'</p>')+'</section>'+cta()
def detail(p):
 category='Courses' if p['type']=='course' else 'Internships';return f'''<section class="page-hero detail-hero"><div class="container"><nav class="breadcrumbs" aria-label="Breadcrumb">{link('index.html','Home')}<span>/</span>{link(category.lower()+'.html',category)}<span>/</span>{E(p['name'])}</nav><span class="eyebrow">{E(p['mode'])} · {E(p['duration'])}</span><h1>{E(p['name'])}</h1><p>{E(p['description'])}</p><div class="hero-actions">{btn('#enquire','Enquire about this program')}{btn('#curriculum','Explore the curriculum',True)}</div></div></section><section class="section container"><div class="detail-grid"><div><h2>Your path, at a glance.</h2><p>{E(p['eligibility'])}</p><h3 class="mt-4">What you’ll learn</h3>{check_list(p['outcomes'])}<h3 class="mt-4">Illustrative project ideas</h3>{check_list(p['projects'])}<p class="fineprint">Project scope is confirmed during the program. These examples are not claims of client-owned or commercially deployed work.</p><div id="curriculum" class="mt-5">{heading('THE CURRICULUM','A foundation you can build on.')}{accordion([(m['title'],m['description']) for m in p['curriculum']],p['id']+'-curriculum')}</div></div><aside class="detail-aside"><div class="fee-card"><span class="eyebrow">YOUR LEARNING INVESTMENT</span><strong class="big-fee">{money(p['fee'])}</strong><p>Program fee</p><dl><div><dt>Duration</dt><dd>{E(p['duration'])}</dd></div><div><dt>Mode</dt><dd>{E(p['mode'])}</dd></div><div><dt>Career support</dt><dd>{'Included' if p['careerSupport'] else 'Practical learning only'}</dd></div></dl>{btn('#enquire','Book a Counselling Session')}<p class="fineprint">Confirm batch schedules, payment terms and certificate requirements before enrolment.</p></div></aside></div></section><section class="section soft"><div class="container">{heading('SUPPORT ALONG THE WAY','Build more than technical knowledge.' if p['careerSupport'] else 'Learn through practical implementation.')}{benefits() if p['careerSupport'] else check_list(p['highlights'])}<p class="fineprint">{E(C['placementNote'] if p['careerSupport'] else C['frontEndNote'])}</p>{('<p>'+E(C['certificateNote'])+'</p><p>'+E(C['feesNote'])+'</p>') if p['type']=='internship' else '<p>Includes program-level internship and career-support benefits. Ask the team how the practical experience fits your course schedule.</p>'}</div></section><section class="section container"><div class="contact-layout" id="enquire"><div>{heading('TAKE THE NEXT STEP','Let’s talk about your goals.','We’ll help you understand the schedule, learning expectations and right starting point.')}<p>{E(C['placementNote'])}</p>{contact_details()}</div>{form(p['id'])}</div></section><section class="section container">{heading('PROGRAM QUESTIONS','Before you begin.')}{accordion(C['faqs'][6:],'detail-faq')}</section>'''
def contact_details():
 c=CONTACT;out='<div class="contact-details">'
 if c['phone']:out+='<div><span>CALL OUR TEAM</span>'+link('tel:+'+c['phoneCountryCode']+re.sub(r'\D','',c['phone']),E(c['phone']))+'</div>'
 if c['email']:out+='<div><span>EMAIL US</span>'+link('mailto:'+c['email'],E(c['email']))+'</div>'
 out+='<div><span>FIND US IN AGRA</span><p>'+E(c['address'])+'<br>'+E(c['state'])+'</p></div>'+whatsapp()+'</div>';return out

def article_card(a):return f'<article class="article-card"><span class="eyebrow">{E(a["category"])}</span><span class="draft-badge">{E(a["status"])}</span><h3>{link("blog/"+a["id"]+".html",E(a["title"]))}</h3><p>{E(a["summary"])}</p>{link("blog/"+a["id"]+".html","Read article "+icon("arrow"),"text-link")}</article>'
def standard(key):
 if key=='career-support':return pagehero(key,'Build the problem-solving, communication and professional habits that support your technical skills.')+'<section class="section container"><div class="support-layout"><div>'+heading('YOUR CAREER ROADMAP','Progress with a purpose.','Support is included in both flagship courses and the Java and Full Stack internships.')+'<p>'+E(C['placementNote'])+'</p></div>'+roadmap()+'</div></section><section class="section soft"><div class="container">'+benefits()+'</div></section>'+cta()
 if key=='team':return pagehero(key,'Meet the trainers, industry experts and mentor supporting your learning journey.')+'<section class="section container">'+team()+'</section>'+cta()
 if key=='placements':return pagehero(key,'Turn your learning and projects into a clearer story for your next opportunity.')+'<section class="section container"><div class="support-layout"><div>'+heading('PREPARATION, WITH SUPPORT','Build a profile you can stand behind.')+'<p>'+E(C['placementNote'])+'</p><p>Our placement-support pathway covers resume guidance, technical preparation, mock interviews, interview-scheduling support and job-application guidance.</p>'+btn('contact.html','Talk to our team')+'</div>'+roadmap()+'</div><div class="notice mt-5"><strong>A transparent approach to outcomes</strong><p>Verified student outcomes will be added when available and approved. We do not publish unverified placement statistics, salaries or employer logos.</p></div></section>'+cta()
 if key=='blog':return pagehero(key,'Learning paths, practical project ideas and thoughtful preparation for a career in development.')+'<section class="section container"><p class="notice">Editorial previews: these initial articles are clearly labelled drafts for review.</p><div class="article-grid">'+''.join(article_card(a) for a in C['articles'])+'</div></section>'+cta()
 if key=='contact':return pagehero(key,'Have a question about a course, internship or where to begin? We’re here to help.')+'<section class="section container"><div class="contact-layout"><div>'+heading('A CONVERSATION IS A GOOD START','Your next step starts here.')+contact_details()+'<div class="location-card">'+icon('location')+'<strong>'+E(CONTACT['address'])+'</strong><p>Contact us for the exact institute location and directions before your visit.</p>'+ (link(CONTACT['mapUrl'],'Open verified map '+icon('arrow'),'text-link') if CONTACT['mapUrl'] else '')+'</div></div>'+form()+'</div></section>'
 if key in C['legal']:return pagehero(key)+'<section class="section container legal-content"><p class="notice">'+E(C['legal']['notice'])+'</p>'+''.join('<h2>'+E(t)+'</h2><p>'+E(d)+'</p>' for t,d in C['legal'][key])+contact_details()+'</section>'
 return ''
