def write(path,body,title,desc,active='index',extra_schema=None,draft=False):
 depth=len(Path(path).parts)-1; prefix='../'*depth
 canonical=ORIGIN.rstrip('/')+'/'+('' if path=='index.html' else path)
 org={'@context':'https://schema.org','@type':'Organization','name':B['name'],'url':ORIGIN,'logo':ORIGIN.rstrip('/')+'/'+B['logo'],'parentOrganization':{'@type':'Organization','name':B['parentName'],'url':B['parentUrl']}}
 schema=[org]
 if extra_schema:schema+=extra_schema
 schema_json=json.dumps(schema,ensure_ascii=False).replace('<', chr(92)+'u003c')
 head=f'<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{E(title)}</title><meta name="description" content="{E(desc)}"><link rel="canonical" href="{E(canonical)}"><meta property="og:type" content="website"><meta property="og:title" content="{E(title)}"><meta property="og:description" content="{E(desc)}"><meta property="og:url" content="{E(canonical)}"><meta property="og:image" content="{E(ORIGIN+"/"+C["seo"]["socialImage"])}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{E(title)}"><meta name="twitter:description" content="{E(desc)}"><meta name="twitter:image" content="{E(ORIGIN+"/"+C["seo"]["socialImage"])}"><link rel="icon" href="assets/images/app-icon.png"><link rel="stylesheet" href="assets/css/bootstrap.min.css"><link rel="stylesheet" href="assets/css/style.css"><script type="application/ld+json">{schema_json}</script>'
 if C['tracking']['searchConsoleVerification']:head+='<meta name="google-site-verification" content="'+E(C['tracking']['searchConsoleVerification'])+'">'
 if draft:head+='<meta name="robots" content="noindex,follow">'
 fallback={'contact':{k:CONTACT[k] for k in ['email','phone','whatsapp']},'forms':{'endpoint':''},'tracking':{},'programs':[{'id':p['id'],'type':p['type'],'name':p['name']} for p in P]}
 body=header(active)+'<main id="main">'+body+'</main>'+footer()
 full='<!doctype html><html lang="en"><head>'+head+'</head><body id="top"><a class="skip-link" href="#main">Skip to content</a>'+body+'<script id="safe-config" type="application/json">'+json.dumps(fallback).replace('<','\\u003c')+'</script><script defer src="assets/js/jquery.min.js"></script><script defer src="assets/js/bootstrap.bundle.min.js"></script><script defer src="assets/js/site.js"></script><script defer src="assets/js/forms.js"></script></body></html>'
 if prefix:
  full=re.sub(r'(href|src)="(?!https?:|mailto:|tel:|#)([^"]+)"',lambda m:m[1]+'="'+prefix+m[2]+'"',full)
  full=full.replace('<body id="top">','<body id="top" data-root="'+prefix+'">')
 target=D/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(full);allpaths.append((path,draft))
